const VIEW = { full: "-313.06 -284.86 1652.13 1652.13", header: "-283.47 -281.77 1593.53 1593.53" };

/**
 * The mark, as the contract reads it. Only the orbit is paced by the turn, so only the orbit's
 * phase is carried across a change. The colours change with the state, which is what survives
 * reduced motion.
 */
const SPEC: MarkSpec = {
  id: "glass",
  beads: 8,
  paced: /^cg-[tnf]$/,
  liveClass: "cm-live",
  look: {
    rest: { "--cg-c0": "oklch(0.5 0.045 25)", "--cg-c1": "oklch(0.63 0.05 75)", "--cg-c2": "oklch(0.46 0.045 262)", "--cg-shine": "0.18" },
    live: { "--cg-c0": "oklch(0.56 0.21 25)", "--cg-c1": "oklch(0.8 0.16 75)", "--cg-c2": "oklch(0.52 0.19 262)", "--cg-shine": "0.8" },
  },
  turnVar: "--cg-turn",
  paperVar: "--cg-paper",
  view: VIEW,
};

export type GlassMarkProps = MarkProps;

export function GlassMark(props: GlassMarkProps) {
  const m = useMark(SPEC, props);
  // Memoised as an OBJECT, not a string: React 19 diffs dangerouslySetInnerHTML by identity, and a
  // fresh object every render would rebuild the markup and restart every animation.
  const body = useMemo(
    () => ({ __html: BODY[m.weight].replaceAll("__cmid__", `cg${m.uid}-`) }),
    [m.weight, m.uid],
  );
  return (
    <svg {...m.root}>
      <style>{STYLE}</style>
      <g className={m.live ? undefined : "cg-drift"} dangerouslySetInnerHTML={body} />
    </svg>
  );
}
